WITH with_windows AS (SELECT *, CUME_DIST() OVER w_grp AS sqft_cume_dist, NTILE(4) OVER w_recent AS sqft_bucket FROM stores WINDOW w_grp AS (PARTITION BY city ORDER BY sqft DESC), w_recent AS (PARTITION BY region ORDER BY sqft, id)) SELECT CASE WHEN sqft >= 17643 THEN 'LARGE' ELSE 'SMALL' END AS sqft_tier, APPROX_PERCENTILE(sqft_bucket, 0.95) AS sqft_bucket_p95, SUM(sqft_cume_dist) AS total_sqft_cume_dist FROM with_windows GROUP BY 1;
